import{_ as e,o as a,c as r,a5 as s}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"Tetragonal","description":"","frontmatter":{"title":"Tetragonal","crystalSystem":"tetragonal"},"headers":[],"relativePath":"classification/crystal-systems/tetragonal.md","filePath":"classification/crystal-systems/tetragonal.md","lastUpdated":1790876393000}'),i={name:"classification/crystal-systems/tetragonal.md"};function l(n,t,o,d,c,h){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="tetragonal" tabindex="-1">Tetragonal <a class="header-anchor" href="#tetragonal" aria-label="Permalink to &quot;Tetragonal&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The tetragonal system has two equal horizontal axes and one longer or shorter vertical axis. Crystals are optically uniaxial with a single optic axis parallel to the c-axis; the optic sign is positive in most gem species (negative in a few). The c-axis is the &quot;extraordinary&quot; refractive index direction.</p><h2 id="crystallographic-parameters" tabindex="-1">Crystallographic Parameters <a class="header-anchor" href="#crystallographic-parameters" aria-label="Permalink to &quot;Crystallographic Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td>Axial lengths</td><td>a = b ≠ c</td></tr><tr><td>Interaxial angles</td><td>α = β = γ = 90°</td></tr><tr><td>Symmetry tier</td><td>medium-high</td></tr><tr><td>Optical class</td><td>uniaxial</td></tr><tr><td>Optic sign</td><td>+</td></tr><tr><td>Birefringence</td><td>0.040–0.300</td></tr><tr><td>Cleavage</td><td>parallel to base (001)</td></tr><tr><td>Habit</td><td>Square prisms, four-sided bipyramids, tabular</td></tr></tbody></table><h2 id="notable-gem-species" tabindex="-1">Notable Gem Species <a class="header-anchor" href="#notable-gem-species" aria-label="Permalink to &quot;Notable Gem Species&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Refractive Index</th><th>Specific Gravity</th></tr></thead><tbody><tr><td>Zircon</td><td>1.810–2.024</td><td>4.60–4.80</td></tr><tr><td>Rutile</td><td>2.616–2.903</td><td>4.20–5.20</td></tr><tr><td>Idocrase (Vesuvianite)</td><td>1.700–1.732</td><td>3.32–3.42</td></tr><tr><td>Scapolite</td><td>1.540–1.579</td><td>2.57–2.78</td></tr><tr><td><em>See the <a href="./../intro.html">classification overview</a> for all crystal systems.</em></td><td></td><td></td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://www.open.edu/openlearn/science-maths-technology/an-introduction-minerals-and-rocks-under-the-microscope/content-section-1.6.3/?tip=linktip" target="_blank" rel="noreferrer">Open University: Crystal systems</a><span>Crystal systems, axial relationships, and symmetry basics</span><small>Open source ↗</small></li><li><a href="https://australian.museum/learn/minerals/what-are-minerals/crystallography/" target="_blank" rel="noreferrer">Australian Museum: Crystallography</a><span>Crystal structure and mineralogical classification context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/summer-2025-phenomenal-gemstones" target="_blank" rel="noreferrer">GIA: Structures Behind the Spectacle</a><span>Structural and optical observation clues in gemology</span><small>Open source ↗</small></li></ul></aside>',8)])])}const g=e(i,[["render",l]]);export{p as __pageData,g as default};
